def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        # Find all indices in this row where value is x
        indices = [j for j, val in enumerate(row) if val == x]
        # Sort indices in descending order
        indices.sort(reverse=True)
        for j in indices:
            result.append((i, j))
    return result

